import{_ as r,C as o,o as n,c as i,j as t,a as s,E as d,a2 as l}from"./chunks/framework.CeZVUxyP.js";const v=JSON.parse('{"title":"Research plan: from evidence to a playable room","description":"","frontmatter":{},"headers":[],"relativePath":"research/strategy.md","filePath":"research/strategy.md","lastUpdated":1794255962000}'),c={name:"research/strategy.md"};function h(m,e,p,u,g,b){const a=o("AudioSummary");return n(),i("div",null,[e[0]||(e[0]=t("h1",{id:"research-plan-from-evidence-to-a-playable-room",tabindex:"-1"},[s("Research plan: from evidence to a playable room "),t("a",{class:"header-anchor",href:"#research-plan-from-evidence-to-a-playable-room","aria-label":'Permalink to "Research plan: from evidence to a playable room"'},"​")],-1)),d(a,{id:"strategy"}),e[1]||(e[1]=l('<p><strong>Reviewed: 2026-11-09.</strong> This is an initial source review and proposed experiment plan. External demonstrations have not been independently reproduced by this lab.</p><h2 id="recommendation" tabindex="-1">Recommendation <a class="header-anchor" href="#recommendation" aria-label="Permalink to &quot;Recommendation&quot;">​</a></h2><p>Start with Blender and Python for editable assets, CadQuery for precision geometry, and one small game prototype. Evaluate a hosted mesh generator alongside scripted modeling. Use REA to investigate one bounded mechanic in a small, inspectable game. Select the game engine after a short integration test.</p><p>Our main question is: <strong>How much useful, editable, tested work can an AI complete, and how much human repair does it require?</strong></p><h2 id="four-separate-research-tracks" tabindex="-1">Four separate research tracks <a class="header-anchor" href="#four-separate-research-tracks" aria-label="Permalink to &quot;Four separate research tracks&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Track</th><th>Question</th><th>Deliverable</th></tr></thead><tbody><tr><td><a href="./rea.html#documented-game-examples">REA and games</a></td><td>Can an agent recover a behavior with verifiable evidence?</td><td>A behavior specification and independent tests</td></tr><tr><td><a href="./ai-modeling.html">3D and CAD</a></td><td>Which workflow produces useful geometry and survives revisions?</td><td>Editable source, exported asset, and quality report</td></tr><tr><td><a href="./ai-stack.html">Languages and libraries</a></td><td>Which stack lets the agent build and repair our feature reliably?</td><td>A working feature and regression test</td></tr><tr><td>Integration</td><td>Can the outputs function together?</td><td>A playable room with a door, prop, interaction, and sound</td></tr></tbody></table><h2 id="evidence-levels" tabindex="-1">Evidence levels <a class="header-anchor" href="#evidence-levels" aria-label="Permalink to &quot;Evidence levels&quot;">​</a></h2><p>Label every finding as one of: <strong>documented API</strong>, <strong>author-reported demonstration</strong>, <strong>independently reproduced</strong>, or <strong>validated in our game</strong>. Repository popularity and attractive videos do not move a claim up this ladder. A documented feature is evidence of an available interface, not evidence that it will meet our quality target.</p><p>For every candidate, record its exact version, source URL, review date, host requirements, license/asset terms, price at test time, and known limitations. Keep inputs, prompts, failures, and cleanup revisions alongside the best output.</p><h2 id="first-experiment-sequence" tabindex="-1">First experiment sequence <a class="header-anchor" href="#first-experiment-sequence" aria-label="Permalink to &quot;First experiment sequence&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Experiment</th><th>Same brief for each candidate</th><th>Main acceptance checks</th></tr></thead><tbody><tr><td>EXP-005: REA behavior recovery</td><td>A small movement, aiming, or sound-pan function; hide known source during analysis</td><td>Compare inferred behavior with ground truth and boundary cases</td></tr><tr><td>EXP-006: Editable prop</td><td>A crate with named lid and body, prescribed dimensions, pivot, and material budget</td><td>Correct dimensions; lid opens; clean engine import; revision succeeds</td></tr><tr><td>EXP-007: Precision CAD</td><td>A bracket with specified holes, thickness, and spacing</td><td>Dimensions and valid solid; change one parameter without breaking the model</td></tr><tr><td>EXP-008: Code and repair</td><td>An opening door with interaction range and a reset action</td><td>Correct behavior; deliberately introduced bug fixed; no regressions</td></tr><tr><td>EXP-009: End-to-end room</td><td>Integrate one accepted prop and door with sound</td><td>Packaged build works; collision, scale, audio, and frame time checked</td></tr></tbody></table><p>These are proposed extensions to EXP-001 through EXP-004, not completed tests.</p><h2 id="how-to-compare-fairly" tabindex="-1">How to compare fairly <a class="header-anchor" href="#how-to-compare-fairly" aria-label="Permalink to &quot;How to compare fairly&quot;">​</a></h2><ol><li>Write the specification and acceptance tests before prompting.</li><li>Establish a manual or known-good baseline.</li><li>Give each workflow the same inputs, iteration limit, and time budget.</li><li>Run at least three independent attempts when practical; report the range as well as the best result.</li><li>Request a realistic change after the first success. Editability matters more than a single attractive render.</li><li>Count prompting, cleanup, integration, and verification in total human time.</li></ol><p>Use the same model and comparable tool access for language comparisons where possible. Keep documentation available for both candidates. Report engine and tooling effects separately from language effects; this is not a universal language leaderboard.</p><h2 id="measures-that-matter" tabindex="-1">Measures that matter <a class="header-anchor" href="#measures-that-matter" aria-label="Permalink to &quot;Measures that matter&quot;">​</a></h2><ul><li><strong>Correctness:</strong> acceptance checks passed, defects, and regressions.</li><li><strong>3D usefulness:</strong> silhouette, dimensions, topology, UVs, materials, pivots, collision, and export behavior.</li><li><strong>Editability:</strong> success of the second requested change and time to make it.</li><li><strong>Efficiency:</strong> generation time, human minutes, retries, and actual cost.</li><li><strong>Runtime:</strong> frame time, memory, and loading on the chosen target hardware.</li><li><strong>Traceability:</strong> source and asset provenance, versions, and repeatable steps.</li></ul><p>Do not compress all of these into a single score initially. A cheap mesh with hours of cleanup may lose to a slower script that remains editable.</p><h2 id="decision-gates" tabindex="-1">Decision gates <a class="header-anchor" href="#decision-gates" aria-label="Permalink to &quot;Decision gates&quot;">​</a></h2><p><strong>First:</strong> one prop and one mechanic pass their tests. <strong>Next:</strong> both survive a change request. <strong>Then:</strong> the integrated room runs on our target machine. Expand to characters, rigging, large environments, or runtime AI only after these gates.</p><p>Use the <a href="./../experiments/template.html">experiment template</a> for every trial. The next concrete step is EXP-006: a small editable prop made with Blender Python, compared with a generated mesh.</p>',21))])}const y=r(c,[["render",h]]);export{v as __pageData,y as default};
